const labEnv = (k, d) => { let v; try { v = $env[k]; } catch (e) { throw new Error('n8n blocks $env in Code nodes (N8N_BLOCK_ENV_ACCESS_IN_NODE is not "false"). Set N8N_BLOCK_ENV_ACCESS_IN_NODE=false for this n8n (deploy/n8n/docker-compose.n8n.yml does) so the copilot can read ' + k + '. Failing closed instead of guessing a scope.'); } return (v === undefined || v === null || v === '') ? d : String(v); };
const ENGAGEMENT_HEADER = "RULES OF ENGAGEMENT for this engagement (set by the operator running the lab):";
function engagementText(e) {
  if (!e || typeof e !== 'object' || Array.isArray(e)) return '';
  const s = (v) => (v === undefined || v === null ? '' : String(v).trim());
  const joined = (v) => (Array.isArray(v) ? v : []).map(s).filter(Boolean).join(', ');
  const lines = [];
  if (s(e.name)) lines.push('ENGAGEMENT: ' + s(e.name) + (s(e.version) ? ' (version ' + s(e.version) + ')' : ''));
  for (const [label, value] of [['SCOPE STATEMENT', s(e.scope_statement)], ['IN SCOPE', joined(e.scope_in)], ['OUT OF SCOPE', joined(e.scope_out)]]) if (value) lines.push(label + ': ' + value);
  if (s(e.window_start) || s(e.window_end)) lines.push('WINDOW: ' + (s(e.window_start) || 'open') + ' to ' + (s(e.window_end) || 'open'));
  for (const [label, value] of [['PROHIBITED', joined(e.prohibited)], ['RULES', s(e.roe)]]) if (value) lines.push(label + ': ' + value);
  const text = lines.join('\n');
  return text.length <= 4000 ? text : text.slice(0, 4000) + ' ...';
}
const j = $json, pol = j.policy || {};
const operatorModel = j.operatorModel || labEnv('COPILOT_OPERATOR_MODEL', 'glm-abl');
const judgeModel = j.judgeModel || labEnv('COPILOT_JUDGE_MODEL', 'qwen3:8b');
if (/(^|[-_:./])abl($|[-_:./])|abliterat|uncensor/i.test(judgeModel) || judgeModel === operatorModel) {
  throw new Error('judge model "' + judgeModel + '" refused: the judge must be a regular model, never the abliterated operator. Choose another judge in the console.');
}
const rules = engagementText(j.engagement);
const judgePrompt = 'TASK: ' + j.task + '\nTARGET: ' + pol.target + (rules ? '\n' + ENGAGEMENT_HEADER + '\n<<<\n' + rules + '\n>>>' : '')
  + '\nPROPOSED COMMAND (already passed the scope + denylist gate):\n' + pol.command + '\nread-only: ' + (pol.readOnly ? 'true' : 'false') + '  tier: ' + (pol.tier || 'none');
return [{ json: { ...j, judgeModel, judgePrompt } }];
